synthesis.csharp_api:
// ============================================================================
// Misery.ModApi -- the ENTIRE public C# surface. Nothing here is `unsafe`.
// No UObject, no FName, no IntPtr, no ProcessEvent, no address, no Task,
// no SynchronizationContext, no version number a mod is expected to compare.
// ============================================================================
namespace Misery.ModApi;

// ---------------------------------------------------------------- identity --
public readonly struct ModId : IEquatable<ModId>
{
    internal ModId(string value);          // internal ctor: a mod cannot forge one
    public string Value { get; }
    public bool Equals(ModId other);
    public override string ToString();
}

public enum UnloadReason { UserRequest, GameShutdown, DependencyUnloaded, Quarantined, LoadFailed }

public interface IMod
{
    void OnLoad(IModContext ctx);
    // Runs while the mod is STILL LIVE, before quiescing, under a wall-clock budget.
    // Every ctx member is legal here. There is deliberately no OnUnloaded.
    void OnUnloading(IModContext ctx, UnloadReason reason);
}
public abstract class ModBase : IMod
{
    public virtual void OnLoad(IModContext ctx) { }
    public virtual void OnUnloading(IModContext ctx, UnloadReason reason) { }
}

// The context is PUSHED to OnLoad. There is no ModApi.Current, no static accessor,
// no service locator, no way to name another mod's namespace.
public interface IModContext
{
    ModId       Id         { get; }
    ILog        Log        { get; }        // always present; the only thread-agnostic member
    IGameThread GameThread { get; }        // always present
    CancellationToken Unloading { get; }   // cancelled the instant Quiescing begins

    // The ONLY way to reach any subsystem. There is no Require<T>() and no
    // ctx.Console property, so using an unavailable capability is a compile
    // error, not a runtime one. A capability listed in the manifest's
    // "require" block cannot fail here -- the mod was refused at plan time.
    bool TryGet<T>(out T capability) where T : class, ICapability;

    int CapabilityCount { get; }
    CapabilityInfo CapabilityAt(int index);   // for bug reports, never for branching
}

public interface ICapability { }
public enum CapabilityState : byte { Absent = 0, Active = 1, Deprecated = 2, Sunset = 3 }
public readonly record struct CapabilityInfo(string Id, int Major, int Minor,
                                             CapabilityState State, string? Replacement);

// ------------------------------------------------------------- error model --
public enum Subsystem : ushort
{
    Core = 1, Log = 2, GameThread = 3, Events = 4, Input = 5, Settings = 6,
    Services = 7, Items = 8, Console = 9, Diagnostics = 10, Host = 11, Managed = 12
}

public readonly struct ModError
{
    public Subsystem Subsystem { get; }
    public ushort    Code      { get; }
    public string    Symbol    { get; }    // "not_owner", "already_registered"
    public string    Detail    { get; }
    public int       Raw       { get; }    // the packed MbStatus, for logs
    public override string ToString();     // "items/already_registered: ..."
}

// THE SPLIT RULE, stated once and applied everywhere:
//   a CONTRACT VIOLATION throws;  a CONTESTED OUTCOME returns a result.
// This mirrors Stage 2 exactly: registry.py's Result vs definition.py's DefinitionError.
public class ModApiException : Exception { public ModError Error { get; } public ModId Mod { get; } }
public sealed class WrongThreadException         : ModApiException { }
public sealed class StaleHandleException         : ModApiException { }
public sealed class NotOwnerException            : ModApiException { }
public sealed class ModQuiescingException        : ModApiException { }
public sealed class NamespaceViolationException  : ModApiException { }
public sealed class InvalidDefinitionException   : ModApiException { public string Field { get; } }
public sealed class UndeclaredFieldException     : ModApiException { public string Name { get; } }
public sealed class FieldMissingException        : ModApiException { public string Name { get; } }

// -------------------------------------------------------------- logging ----
public enum LogLevel { Trace = 0, Debug = 1, Info = 2, Warn = 3, Error = 4 }

public readonly struct LogField
{
    public static LogField Of(string key, long value);
    public static LogField Of(string key, double value);
    public static LogField Of(string key, bool value);
    public static LogField Of(string key, string value);
}

public interface ILog
{
    bool IsEnabled(LogLevel level);
    void Trace(string message);
    void Debug(string message);
    void Info (string message);
    void Warn (string message);
    void Error(string message);
    void Error(string message, Exception cause);
    void Write(LogLevel level, string message, params LogField[] fields);
    ILog Channel(string name);              // emitted as "<mod_id>/<name>"
}

// ------------------------------------------------------------ game thread --
public interface IGameThread
{
    bool IsCurrent { get; }

    // Callable from ANY thread. Runs on the next drain. The post is a ledger
    // resource: outstanding work whose owner quiesces is DROPPED, not run.
    void Post(Action work);

    void AssertCurrent([CallerMemberName] string? member = null);   // WrongThreadException
    TimeSpan CallbackWarnBudget { get; }

    // There is deliberately NO Task, NO PostAsync, NO SwitchTo, NO
    // SynchronizationContext and NO TaskScheduler in v1. The framework never
    // hands out a continuation, so the framework can never root one inside a
    // collectible ALC. Background work is `Task.Run(...)` the mod owns, ending
    // in `ctx.GameThread.Post(...)`. See EXPLICITLY DEFERRED.
}

// ------------------------------------------ the ONE payload concept: bags ---
public enum FieldType : byte { Int64 = 0, Double = 1, Bool = 2, String = 3 }

/

synthesis.ownership_model:
A MOD NEVER FETCHES ITS CONTEXT AND NEVER NAMES ITS NAMESPACE. Stage 4's resolver produces the load plan; for each mod in load order the host calls `mod_begin(mod_id)` — a **host-only** function, reachable only through the `misery.host` capability, which `acquire_capability` refuses (`MB_E_DENIED`) to any owner that is not the host handle minted by `MbAcquireRoot`. `mod_id` comes from the manifest, exactly as `execution.py` already attaches it to item declarations. Only after `mod_require` has resolved every declared capability does `mod_activate` run and the managed shim construct an `IModContext` around the returned `MbHandle` and push it into `IMod.OnLoad(ctx)`. There is no `ModApi.Current`, no `GetContext(id)`, no `mod_open(mod_id)` anywhere in the mod-reachable surface — the identity-forgery primitive the judges named in Leased Context does not exist here.

THE DATA STRUCTURE IS ONE LEDGER, NOT N REGISTRIES.

    FModRecord { interned mod_id; uint32 epoch; uint8 state; uint32 ledger_head;
                 uint32 owned_count; int32 active_frames; uint64 granted_caps; }
    FOwned     { uint8 kind; uint32 next; MbReleaseFn release; void* subsystem; uint64 payload; }
    FSlot      { uint32 tag; uint8 kind, alive; uint32 owner_slot, owner_epoch;
                 uint32 pin_count; uint64 cookie; void* body; }

Every capability that hands a mod anything — a subscription, an event channel, an input action, a setting, a published service, a service import, an item registration, a console command, a log channel, a payload bag, an acquired capability table, a pending GameThread post — pushes exactly one `FOwned` node onto the owning mod's intrusive LIFO chain. Push is O(1) and allocation-free. Teardown is one walk of that chain to empty. That is the WHOLE teardown path, which is why a subsystem added in 2031 becomes deterministically unloadable by pushing a thunk rather than by editing unload.

LIFO IS LOAD-BEARING, not tidiness: a service import acquired while handling a settings change must be revoked before the settings watch that reached it. Insertion order is the only ordering that is correct without the ledger knowing what the resources mean. The walk is `while (head)`, not a fixed-length reverse scan, so a node pushed by another node's release thunk is still collected.

TWO PROPERTIES THE JUDGES ASKED FOR AND EACH RIVAL ONLY HALF-HAD:
- **`MbHandle owner` is the first parameter of every function in every table, reads included.** `MB_E_NOT_OWNER` is reachable everywhere. Handle Wall could not perform this check at all; Lattice performed it on writes only.
- **Mod slots are never recycled.** A `mod_id`, once loaded, owns its slot for the process lifetime, and its id string is interned. This makes mod-handle ABA structurally impossible, makes off-thread logging safe against concurrent teardown (the log path touches only the interned id), and means a leaked resource stays attributed to the mod that leaked it forever — no future mod inherits a dead identity. Resource-slot tags are CSPRNG-drawn 32-bit values, never reused for a slot; a slot whose tag space exhausts is retired permanently, so resource ABA is also impossible.

A RELEASE THUNK THAT FAILS does not abort the walk. It is counted into the unload report's `leaked`, logged as a structured error against the `mod_id`, and the record moves to `MB_MOD_LEAKED` rather than `DEAD`. This is Stage 2's registry rule generalised — `registry.py` keeps a registration when `dematerialize` fails rather than dropping it into an unreachable leak.

A SUBSCRIPTION TORN DOWN MID-DISPATCH IS NOT INVOKED. Dispatch never iterates captured callbacks; it snapshots subscription HANDLES and re-resolves each one immediately before invoking it, through the single `mb_resolve` predicate. A subscription retired at index 3 while the loop sits at index 1 fails the tag/epoch/state test and is skipped and counted. **Copy-the-subscriber-list dispatch is explicitly rejected**: it would invoke a retired subscription from the snapshot, which is one step from a callback after unload.

THE REMOVAL/ADDITION ASYMMETRY IS DELIBERATE AND STATED: removal takes effect immediately, mid-dispatch. Addition does not — `count` is captured before the loop, so a subscription created during a dispatch first fires on the next raise. That makes an unbounded raise impossible, makes the invoked set a deterministic function of the state at raise time, and matches the existing `GameThreadDispatcher`'s documented policy that nested work runs on the next drain. Delivering to a new subscriber late is correctness-neutral; delivering to a retired one is a use-after-unload.

TEARDOWN IS TWO-PHASE, and this is the graft that fixes Lattice's one real ownership hole. `release_fn` is contractually forbidden from freeing memory a live frame can reach: it tombstones and unlinks only. Actual frees go on a pending list drained solely when `g_depth == 0` and every `pin_count == 0`. So RELEASE is immediate and deterministic (the stated requirement) while RECLAMATION is deferred (the safety), and no future subsystem author has to know an unwritten invariant.
